'use strict';
const ExamUI=(()=>{
const title=e=>e.title||`${e.number}º Exame de Ordem`;
let bank=null,active=null,draft=null,store={},saved=true,clock=null;
try{const raw=JSON.parse(localStorage.getItem('saber-exams-v1')||'{}');if(raw&&typeof raw==='object'&&!Array.isArray(raw))store=raw;}catch{saved=false;}
function stop(){if(clock!==null){clearInterval(clock);clock=null;}}
function persist(){store[active.id]=draft;try{localStorage.setItem('saber-exams-v1',JSON.stringify(store));}catch{saved=false;}}
function warning(){return saved?'Respostas salvas neste aparelho.':'Não foi possível salvar. Mantenha o app aberto para conservar as respostas desta sessão.';}
function link(url,label){return `<a class="primary exam-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;}
async function list(){stop();stopTimer();round=[];currentScreen='exams';render('<h1>Preparando os simulados…</h1>');try{if(!bank){const r=await fetch('./exams.json');if(!r.ok)throw Error('EXAMES-CARGA');bank=ExamEngine.validate(await r.json());}if(currentScreen!=='exams')return;render(`<button class="back" id="exam-home">‹ Voltar ao início</button><span class="eyebrow">PROVAS OFICIAIS · OAB E CARREIRAS JURÍDICAS</span><h1>Questões de banca, sem adaptação.</h1><p>OAB 42º ao 47º + Delegado PCMG, Defensor DPE-PE e Promotor MPRJ (2025). Cadernos tipo 1.</p><div class="notice"><div>Abra o caderno oficial em PDF e marque as alternativas no cartão do app. O gabarito aparece ao finalizar. A abertura do PDF precisa de internet; depois de baixado, ele pode ser consultado no leitor do aparelho.</div></div><div class="themes">${bank.map((e,i)=>{const old=store[e.id],valid=ExamEngine.validDraft(old,e);return `<button class="theme" data-exam="${i}"><strong>${esc(title(e))}</strong><span>${e.date.split('-').reverse().join('/')} · ${valid?(old.finishedAt?'Ver último resultado':'Continuar simulado'):'Começar simulado'} →</span></button>`;}).join('')}</div><p>Gabaritos definitivos: OAB conferida em 20/10/2026; concursos conferidos em 22/10/2026. Nos concursos, a pontuação aqui é de treino: não calcula notas mínimas por bloco, classificação ou aprovação do edital. Questões anuladas recebem um ponto. O resultado é de treino, sem vínculo com a OAB/FGV.</p>`);document.getElementById('exam-home').onclick=home;root.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>choose(bank[Number(b.dataset.exam)]));}catch{if(currentScreen!=='exams')return;render('<h1>Não foi possível abrir os simulados.</h1><p>Código EXAMES-CARGA. Os outros modos continuam disponíveis.</p><button id="exam-home" class="primary">Voltar ao início</button><button id="exam-reload" class="primary">Tentar novamente</button>');document.getElementById('exam-home').onclick=home;document.getElementById('exam-reload').onclick=list;}}
function choose(e){active=e;const old=store[e.id];if(ExamEngine.validDraft(old,e)){draft=old;if(draft.finishedAt)return result();if(ExamEngine.expired(draft))return finish();return question();}setup();}
function setup(){stop();currentScreen='exam-setup';render(`<button class="back" id="exam-back">‹ Escolher outro exame</button><span class="eyebrow">${esc(title(active))} · TIPO 1 · BRANCA</span><h1>Faça a prova no seu ritmo.</h1><p>1. Abra ou baixe o caderno branco oficial.<br>2. Volte ao app e inicie o cartão de respostas.<br>3. Marque de A a ${ExamEngine.choices(active).at(-1)}; confira sua nota ao finalizar.</p>${link(active.paperUrl,'Abrir caderno oficial (PDF)')}<label class="clock-choice"><input id="exam-timed" type="checkbox"> Simular o tempo de prova: ${active.durationMinutes} minutos corridos</label><p>Com cronômetro, o tempo continua contando enquanto você consulta o PDF ou sai do app. Sem cronômetro, você pode estudar aos poucos. ${active.kind==='concurso'?'Este treino tem cinco alternativas por questão e não simula critérios eliminatórios por bloco do edital.':''}</p><button class="primary" id="exam-start">Iniciar simulado →</button><p>O gabarito corresponde à legislação e aos critérios daquela edição. Este modo não oferece comentários jurídicos individuais.</p>`);document.getElementById('exam-back').onclick=list;document.getElementById('exam-start').onclick=()=>{draft=ExamEngine.fresh(active,document.getElementById('exam-timed').checked);persist();question();};}
function question(){stop();currentScreen='exam-card';if(ExamEngine.expired(draft))return finish();const p=draft.position,count=draft.answers.filter(v=>v!==null).length;render(`<button class="back" id="exam-exit">‹ Salvar e sair</button><span class="eyebrow">${esc(title(active))} · CADERNO BRANCO · TIPO 1</span><h1>Questão ${p+1} de ${active.answers.length}</h1><div class="game-hud"><span>${count}/${active.answers.length} marcadas</span><strong id="exam-clock">${draft.deadline?'Calculando tempo…':'Sem cronômetro'}</strong></div>${link(active.paperUrl,'Consultar caderno oficial (PDF)')}<p>Leia a questão ${p+1} no caderno e marque sua resposta abaixo. Você pode alterá-la até finalizar.</p><div class="exam-choices">${ExamEngine.choices(active).map(v=>`<button class="option ${draft.answers[p]===v?'chosen':''}" data-exam-answer="${v}" aria-pressed="${draft.answers[p]===v}" aria-label="Alternativa ${v}">${v}</button>`).join('')}</div><button class="back" id="exam-clear">Deixar em branco</button><div class="actions"><button class="primary" id="exam-prev" ${p===0?'disabled':''}>← Anterior</button><button class="primary" id="exam-next" ${p===active.answers.length-1?'disabled':''}>Próxima →</button></div><p id="exam-save" role="status">${warning()}</p><details><summary>Ir para uma questão · 1 a ${active.answers.length}</summary><div class="exam-grid">${draft.answers.map((v,i)=>`<button class="exam-number ${v?'marked':''}" data-exam-jump="${i}" aria-label="Questão ${i+1}, ${v?'marcada '+v:'em branco'}">${i+1}</button>`).join('')}</div></details><button class="primary" id="exam-finish">Finalizar e corrigir simulado</button>`);
 document.getElementById('exam-exit').onclick=()=>{persist();list();};root.querySelectorAll('[data-exam-answer]').forEach(b=>b.onclick=()=>mark(b.dataset.examAnswer));document.getElementById('exam-clear').onclick=()=>mark(null);document.getElementById('exam-prev').onclick=()=>move(p-1);document.getElementById('exam-next').onclick=()=>move(p+1);root.querySelectorAll('[data-exam-jump]').forEach(b=>b.onclick=()=>move(Number(b.dataset.examJump)));document.getElementById('exam-finish').onclick=()=>{if(confirm(`Finalizar? ${active.answers.length-count} questão(ões) em branco. Após a correção, as respostas ficam bloqueadas.`))finish();};if(draft.deadline){tick();clock=setInterval(tick,1000);}}
function mark(v){if(draft.finishedAt)return;if(ExamEngine.expired(draft))return finish();if(v!==null&&!ExamEngine.choices(active).includes(v))return;draft.answers[draft.position]=v;persist();question();}
function move(p){if(!Number.isInteger(p)||p<0||p>=active.answers.length)return;draft.position=p;persist();question();}
function tick(){if(currentScreen!=='exam-card'){stop();return;}if(ExamEngine.expired(draft)){finish();return;}const s=Math.max(0,Math.ceil((draft.deadline-Date.now())/1000)),el=document.getElementById('exam-clock');if(el)el.textContent=Math.floor(s/3600)+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function finish(){if(!draft.finishedAt){draft.finishedAt=Date.now();persist();}result();}
function result(){stop();currentScreen='exam-result';const g=ExamEngine.grade(active,draft.answers);render(`<span class="eyebrow">${esc(title(active))} · SIMULADO CONCLUÍDO</span><h1>${g.passed===null?'Seu resultado de treino.':g.passed?'Meta de 40 pontos atingida!':'Continue: cada tentativa ensina.'}</h1><div class="score">${g.score}<span> / ${active.answers.length}</span></div><p>${g.correct} acertos + ${g.annulled} anulada(s) = ${g.score} pontos.<br>${g.wrong} erros · ${g.blank} em branco (entre as questões válidas).</p><p>${warning()} O resultado indica seu desempenho neste treino.</p><div class="actions"><button class="primary" id="exam-list">Escolher outro exame</button><button class="primary" id="exam-restart">Refazer este exame</button></div><details><summary>Conferir minhas ${active.answers.length} respostas</summary><div class="exam-review">${g.details.map(d=>`<p><strong>Questão ${d.number}</strong> · Sua resposta: ${d.answer||'em branco'} · ${d.key==='*'?'Anulada: +1 ponto':'Gabarito: '+d.key+' · '+({correct:'Acerto',wrong:'Erro',blank:'Em branco'}[d.status])}</p>`).join('')}</div></details>${link(active.keyUrl,'Ver gabarito definitivo oficial')}<p>Não são exibidos comentários jurídicos neste modo. Consulte sempre a legislação vigente ao revisar uma prova antiga.</p>`);document.getElementById('exam-list').onclick=list;document.getElementById('exam-restart').onclick=()=>{if(confirm('Refazer substituirá o último cartão deste exame. Continuar?')){delete store[active.id];setup();}};}
function back(){if(currentScreen==='exams'){home();return false;}if(currentScreen.startsWith('exam-')){if(draft&&active)persist();list();return false;}return null;}
return {list,stop,back};
})();
